# Let's use python with pysat to solve this 16x16 Sudoku
# First, let's set up the problem

from pysat import *
from pysat.solvers import Glucose3
from itertools import product

n = 16
block_size = 4

# Fixed values from the problem
fixed = {
    5: 6, 13: 14, 14: 15, 18: 7, 22: 3, 26: 15, 27: 16, 33: 10, 34: 11, 42: 3,
    53: 10, 54: 11, 57: 6, 58: 7, 69: 5, 71: 7, 80: 6, 81: 5, 83: 7, 84: 2,
    85: 1, 94: 12, 103: 15, 106: 4, 107: 3, 109: 5, 112: 14, 115: 15, 120: 6,
    135: 6, 136: 11, 140: 15, 141: 16, 148: 3, 150: 1, 170: 1, 175: 6, 185: 8,
    188: 3, 190: 1, 196: 8, 199: 5, 201: 11, 203: 9, 208: 8, 218: 14, 240: 16,
    241: 15, 243: 13, 244: 12, 253: 3
}

# Let's verify indices are in range 0..255
for k in fixed:
    assert 0 <= k < 256, f"Index {k} out of range"

# Variable encoding: for each cell (i,j) and value v (1..16), we have a boolean variable
# We'll use a direct encoding with SAT

# Let's use a simpler approach: encode as a SAT problem
# Variable: x[i][j][v] where i,j in 0..15, v in 1..16
# Map to SAT variable index

def var_id(i, j, v):
    """Return SAT variable id for cell (i,j) having value v"""
    return i * n * n + j * n + v  # v from 1..16

# Total variables needed
total_vars = n * n * n  # 16*16*16 = 4096

solver = Glucose3()

# Each cell must have exactly one value
for i in range(n):
    for j in range(n):
        # At least one value
        solver.add_clause([var_id(i, j, v) for v in range(1, n+1)])
        # At most one value (pairwise)
        for v1 in range(1, n+1):
            for v2 in range(v1+1, n+1):
                solver.add_clause([-var_id(i, j, v1), -var_id(i, j, v2)])

# Each row must have each value exactly once
for i in range(n):
    for v in range(1, n+1):
        # At least one in row
        solver.add_clause([var_id(i, j, v) for j in range(n)])
        # At most one (pairwise)
        for j1 in range(n):
            for j2 in range(j1+1, n):
                solver.add_clause([-var_id(i, j1, v), -var_id(i, j2, v)])

# Each column must have each value exactly once
for j in range(n):
    for v in range(1, n+1):
        solver.add_clause([var_id(i, j, v) for i in range(n)])
        for i1 in range(n):
            for i2 in range(i1+1, n):
                solver.add_clause([-var_id(i1, j, v), -var_id(i2, j, v)])

# Each block must have each value exactly once
for bi in range(block_size):
    for bj in range(block_size):
        cells = [(bi*block_size + i, bj*block_size + j) for i in range(block_size) for j in range(block_size)]
        for v in range(1, n+1):
            solver.add_clause([var_id(i, j, v) for (i, j) in cells])
            for idx1 in range(len(cells)):
                for idx2 in range(idx1+1, len(cells)):
                    i1, j1 = cells[idx1]
                    i2, j2 = cells[idx2]
                    solver.add_clause([-var_id(i1, j1, v), -var_id(i2, j2, v)])

# Add fixed values
for idx, val in fixed.items():
    i = idx // 16
    j = idx % 16
    solver.add_clause([var_id(i, j, val)])

print(f"Solving with {total_vars} variables...")
result = solver.solve()
print(f"Result: {result}")

if result:
    model = solver.get_model()
    # Extract solution
    grid = [0] * 256
    for i in range(n):
        for j in range(n):
            for v in range(1, n+1):
                if model[var_id(i, j, v) - 1] > 0:
                    grid[i * n + j] = v
                    break
    print("Solution found!")
    # Print grid
    for i in range(n):
        row_str = " ".join(f"{grid[i*n+j]:2d}" for j in range(n))
        print(row_str)
        if (i+1) % block_size == 0:
            print()
else:
    print("UNSATISFIABLE")

